    EmpID INT,
    Name VARCHAR(50),
    Salary DECIMAL(10, 2)
);
-- Start a transaction
BEGIN TRANSACTION;
-- Insert a new employee
INSERT INTO Employees (EmpID, Name, Salary) VALUES (1, 'John Doe', 50000);
-- Create a savepoint
SAVEPOINT sp1;
-- Insert another employee
INSERT INTO Employees (EmpID, Name, Salary) VALUES (2, 'Jane Smith', 60000);
-- Create another savepoint
SAVEPOINT sp2;
-- Insert another employee
