    v_temp NUMBER;
    v_digit NUMBER;
    v_sum NUMBER := 0;
BEGIN
    v_temp := v_number;

    WHILE v_temp > 0 LOOP
        v_digit := MOD(v_temp, 10);
        v_sum := v_sum + (v_digit * v_digit * v_digit);
        v_temp := TRUNC(v_temp / 10);
