CREATE OR REPLACE FUNCTION convert_case(str VARCHAR2, case_type VARCHAR2) RETURN 
    VARCHAR2 IS
    result VARCHAR2(4000);
BEGIN
    IF case_type = 'UPPER' THEN
        result := UPPER(str);
    ELSIF case_type = 'LOWER' THEN
        result := LOWER(str);
    ELSE
        result := str; -- Fallback if case_type doesn't match
    END IF;
    RETURN result;
END;
/
